INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "雷彦恭进攻岳州未克", "start_year": 907, "end_year": 907, "time_original": "907年七月条，具体日未载", "dynasty": "唐末五代十国", "description": "雷彦恭进攻岳州，未能攻克。", "phases": [], "location_name": "岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "bcb1840b-829e-5f36-a356-ae784f0a6138"}, {"title": "后梁赐张全义名宗奭", "start_year": 907, "end_year": 907, "time_original": "梁开平元年八月丙午", "dynasty": "唐末五代十国", "description": "后梁赐河南尹张全义名宗奭。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "61df11d1-cd07-5766-b027-d5883400fa34"}, {"title": "后梁令钱镠、马殷兼领淮南与武昌军职", "start_year": 907, "end_year": 907, "time_original": "梁开平元年八月辛亥", "dynasty": "唐末五代十国", "description": "后梁以钱镠兼淮南节度使、马殷兼武昌节度使，并授招讨制置职任。这里只记录授官，不表示二人已实际占有对应辖区。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "d48c8af9-aa4c-57aa-a21e-f653ab35c76d"}, {"title": "周德威在高河击败秦武", "start_year": 907, "end_year": 907, "time_original": "907年八月条，具体日未载", "dynasty": "唐末五代十国", "description": "康怀贞遣秦武进攻屯高河的周德威，秦武战败。", "phases": [], "location_name": "高河", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "1bde1204-9872-5199-ae9c-c8d8e304bcc0"}, {"title": "李思安接掌潞州围军，修筑夹寨", "start_year": 907, "end_year": 907, "time_original": "梁开平元年八月（干支原文作丁已，待校）", "dynasty": "唐末五代十国", "description": "李思安代康怀贞为潞州行营都统，修筑内外夹城及运粮甬道。周德威等反复袭扰，使梁军受困。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "56594a8a-4634-5611-84a9-d3a5ff9675f4"}, {"title": "雷彦恭再攻荆南失利，被后梁削爵讨伐", "start_year": 907, "end_year": 907, "time_original": "梁开平元年九月丙申及此前", "dynasty": "唐末五代十国", "description": "雷彦恭进攻涔阳、公安，被高季昌击退。后梁削其官爵，命高季昌与马殷讨伐。", "phases": [], "location_name": "涔阳、公安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "c9db70c7-1fed-5af8-a739-b0b2c472d3ab"}, {"title": "王建称帝，建立前蜀", "start_year": 907, "end_year": 907, "time_original": "907年九月己亥", "dynasty": "唐末五代十国", "description": "王建未采用冯涓建议称制的意见，采韦庄之谋称帝，国号大蜀；史称前蜀。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "fe13c8b8-7b97-5141-bde8-b2e496f0b1c9"}, {"title": "前蜀任命王宗佶、韦庄、唐道袭", "start_year": 907, "end_year": 907, "time_original": "907年九月辛丑", "dynasty": "唐末五代十国", "description": "王建称帝后任命王宗佶为中书令、韦庄判中书门下事、唐道袭为内枢密使；并封王宗懿为遂王，封王具体日未载。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "a8b0614b-8e01-55bf-8de3-f52ed0feda35"}, {"title": "荆南、楚军攻朗州，许德勋击败淮南援军", "start_year": 907, "end_year": 907, "time_original": "907年十月", "dynasty": "唐末五代十国", "description": "高季昌遣倪可福会秦彦晖攻朗州。杨渥遣泠业、李饶救雷彦恭，马殷遣许德勋迎击；淮南援军战败，泠业、李饶被俘后在长沙处死。", "phases": [], "location_name": "朗州、朗口、浏阳、长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "dd736a34-d63a-59b3-91e7-d10c3e267765"}, {"title": "尹皓攻取晋军江猪岭寨", "start_year": 907, "end_year": 907, "time_original": "梁开平元年十一月甲申", "dynasty": "唐末五代十国", "description": "夹马指挥使尹皓攻取晋军江猪岭寨。", "phases": [], "location_name": "江猪岭寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "e4d42907-4f57-5521-ae13-b1cb1399f2bb"}, {"title": "刘守文起兵攻打刘守光", "start_year": 907, "end_year": 907, "time_original": "907年十一月条，具体日未载", "dynasty": "唐末五代十国", "description": "刘守文得知弟弟刘守光囚父后起兵进攻，双方互有胜负。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "4470dce0-0e2b-5c1f-8f31-b2b7897d1652"}, {"title": "罗绍威劝刘守文归梁，刘延祐入质", "start_year": 907, "end_year": 907, "time_original": "梁开平元年十一月戊子", "dynasty": "唐末五代十国", "description": "罗绍威致书刘守文劝其归梁。刘守文遣使请降，送子刘延祐为质；后梁加授其中书令。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "467cee9e-49ef-5b6e-a56c-b22fc21411f2"}, {"title": "后梁赦免逃亡军士，许文面者还乡", "start_year": 907, "end_year": 907, "time_original": "梁开平元年十一月壬寅", "dynasty": "唐末五代十国", "description": "后梁赦免逃亡军士，允许有军号刺字者还乡。此前跋队斩和刺字制度为段首追叙，不作为本年新设制度。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "abb7f5d9-9f17-5bc2-a219-9ea5b59a5b22"}, {"title": "米志诚袭颍州，梁援军出动后退兵", "start_year": 907, "end_year": 907, "time_original": "907年十一月至十二月甲子", "dynasty": "唐末五代十国", "description": "米志诚率淮南军攻取颍州外郭，张实守子城。后梁十二月发援军，米志诚等退兵。", "phases": [], "location_name": "颍州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "ccb109d3-0568-51d4-b469-bccfcd8447ce"}, {"title": "李存璋攻晋州，后梁令河中、陕州救援", "start_year": 907, "end_year": 907, "time_original": "907年十一月至十二月壬戌", "dynasty": "唐末五代十国", "description": "李克用命李存璋攻晋州，以分散上党方面的梁军；后梁命河中、陕州出兵救援。", "phases": [], "location_name": "晋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "ae19efb9-c6a0-5abe-8dae-cb89db82f5cd"}, {"title": "晋军进攻洺州", "start_year": 907, "end_year": 907, "time_original": "907年十二月丁卯", "dynasty": "唐末五代十国", "description": "《通鉴》记晋军进攻洺州，未在此段指明具体领兵者。", "phases": [], "location_name": "洺州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "6c505c30-5bc1-5481-82b6-8616e432ad83"}, {"title": "淮南军攻信州，危仔倡向吴越求援", "start_year": 907, "end_year": 907, "time_original": "907年十二月条，具体日未载", "dynasty": "唐末五代十国", "description": "淮南军进攻信州，刺史危仔倡向吴越求援。", "phases": [], "location_name": "信州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "fda324ee-3802-57b1-937c-5bc3f3b9d06c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "雷彦恭攻岳州未克。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p045·原文件第50行", "note": "原文：雷彦恭攻岳州，不克。；核对说明：本段只有攻而未克，不据此推断守将或后续归属。", "status": "draft", "id": "32976e7e-72c4-52ea-b331-4e0ed73a9352", "subject_id": "bcb1840b-829e-5f36-a356-ae784f0a6138", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年七月丙申后、八月前；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p045·原文件第50行", "note": "原文：雷彦恭攻岳州，不克。；核对说明：本段只有攻而未克，不据此推断守将或后续归属。", "status": "draft", "id": "6dc0aecd-0836-57f5-89bc-49ec4e866fb9", "subject_id": "bcb1840b-829e-5f36-a356-ae784f0a6138", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "后梁赐张全义名宗奭。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p046·原文件第51行", "note": "原文：八月，丙午，赐河南尹张全义名宗奭。；核对说明：张全义与张宗奭为同一人，沿用已发布实体与事件，不新建人物。", "status": "draft", "id": "8c0dfd7f-0e4c-57e9-9600-f1722423abb8", "subject_id": "61df11d1-cd07-5766-b027-d5883400fa34", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年八月丙午", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p046·原文件第51行", "note": "原文：八月，丙午，赐河南尹张全义名宗奭。；核对说明：张全义与张宗奭为同一人，沿用已发布实体与事件，不新建人物。", "status": "draft", "id": "0362ebc4-69de-52e8-acde-1ebfc1c19366", "subject_id": "61df11d1-cd07-5766-b027-d5883400fa34", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "后梁加钱镠、马殷节度使及招讨制置职。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p047·原文件第52行", "note": "原文：辛亥，以吴越王镠兼淮南节度使，楚王殷兼武昌节度使，各充本道招讨制置使。；核对说明：名义加官不说明两人已实际控制淮南、武昌。", "status": "draft", "id": "43b0cb00-4a88-5f69-b4d8-382a1f92c603", "subject_id": "d48c8af9-aa4c-57aa-a21e-f653ab35c76d", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年八月辛亥", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p047·原文件第52行", "note": "原文：辛亥，以吴越王镠兼淮南节度使，楚王殷兼武昌节度使，各充本道招讨制置使。；核对说明：名义加官不说明两人已实际控制淮南、武昌。", "status": "draft", "id": "2ff79c14-b4f7-5c38-b37e-2bbf9f63dec7", "subject_id": "d48c8af9-aa4c-57aa-a21e-f653ab35c76d", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "周德威驻高河，康怀贞部秦武出击战败。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p048·原文件第53行", "note": "原文：晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。；核对说明：秦武部败与潞州后续夹寨攻守相连，仍保留单独战斗事件。", "status": "draft", "id": "d9b983c2-2abd-58bc-a14d-e6cebb69ed1b", "subject_id": "1bde1204-9872-5199-ae9c-c8d8e304bcc0", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年八月辛亥后；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p048·原文件第53行", "note": "原文：晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。；核对说明：秦武部败与潞州后续夹寨攻守相连，仍保留单独战斗事件。", "status": "draft", "id": "7a8e76c5-84f4-5802-8711-084f894bb1e6", "subject_id": "1bde1204-9872-5199-ae9c-c8d8e304bcc0", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "李思安代康怀贞统兵潞州并筑夹寨。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p049·原文件第54行", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。；核对说明：底本“丁已”疑应校为“丁巳”，保留原字；与第33、39段潞州围城衔接。", "status": "draft", "id": "52964470-de4e-591c-abf5-e1647d263a7e", "subject_id": "56594a8a-4634-5611-84a9-d3a5ff9675f4", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年八月丁已（原文；干支字形待核）", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p049·原文件第54行", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。；核对说明：底本“丁已”疑应校为“丁巳”，保留原字；与第33、39段潞州围城衔接。", "status": "draft", "id": "b9790568-92a5-5463-8cab-ea6b40e47a06", "subject_id": "56594a8a-4634-5611-84a9-d3a5ff9675f4", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "李思安在潞州筑内外夹城，建立运粮甬道；周德威持续袭扰。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p049·原文件第54行", "note": "原文：思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。；核对说明：营垒与粮道建设为过程；不将一天内的任命日等同全部筑城完成日。", "status": "draft", "id": "1e211ecb-8916-5465-a023-1e274cb890d2", "subject_id": "56594a8a-4634-5611-84a9-d3a5ff9675f4", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "雷彦恭攻涔阳公安败后，后梁削其官爵。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p050·原文件第55行", "note": "原文：九月，雷彦恭攻涔阳、公安，高季昌击败之。；核对说明：进攻及战败发生于九月，削官在下句丙申；不强合为同一日。", "status": "draft", "id": "cd32c8af-f014-58e1-83f4-6e8b6f84e623", "subject_id": "c9db70c7-1fed-5af8-a739-b0b2c472d3ab", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年九月；削官在丙申", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p050·原文件第55行", "note": "原文：九月，雷彦恭攻涔阳、公安，高季昌击败之。；核对说明：进攻及战败发生于九月，削官在下句丙申；不强合为同一日。", "status": "draft", "id": "546ccfc1-0ae0-567d-9f21-ff2d40fac212", "subject_id": "c9db70c7-1fed-5af8-a739-b0b2c472d3ab", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "后梁命高季昌与马殷讨伐雷彦恭。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p050·原文件第55行", "note": "原文：丙申，诏削彦恭官爵，命季昌与楚王殷讨之。；核对说明：诏令是朝廷命令，不等于两方后来已经完成讨伐。", "status": "draft", "id": "80cd3332-902f-57ad-9537-d611585931eb", "subject_id": "c9db70c7-1fed-5af8-a739-b0b2c472d3ab", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "王建即帝位，国号大蜀。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p051·原文件第56行", "note": "原文：王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。；核对说明：韦庄之谋被采纳；冯涓仅建议称制而王建未采纳，不误写为独立既成政权方案。", "status": "draft", "id": "c2ffed19-b23e-5b8f-8d38-8cd1e976b236", "subject_id": "fe13c8b8-7b97-5141-bde8-b2e496f0b1c9", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年九月己亥", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p051·原文件第56行", "note": "原文：王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。；核对说明：韦庄之谋被采纳；冯涓仅建议称制而王建未采纳，不误写为独立既成政权方案。", "status": "draft", "id": "e7b46575-41d4-509c-8b7e-02af8ac24886", "subject_id": "fe13c8b8-7b97-5141-bde8-b2e496f0b1c9", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "冯涓主张先由蜀王称制，王建没有采纳。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p051·原文件第56行", "note": "原文：冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。；核对说明：史书原文有“请，以”断句疑点，建议本身仍清楚；不改写为冯涓支持立即称帝。", "status": "draft", "id": "70c6696e-a00b-51eb-8820-190a1d9cd81f", "subject_id": "fe13c8b8-7b97-5141-bde8-b2e496f0b1c9", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "王建称帝后任王宗佶、韦庄、唐道袭等职。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p051·原文件第56行", "note": "原文：辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。；核对说明：官员任命明确在辛丑，与己亥即位相隔，不合并同日。", "status": "draft", "id": "2a15703e-6dbe-5651-999b-0cdbfeae890b", "subject_id": "a8b0614b-8e01-55bf-8de3-f52ed0feda35", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年九月辛丑", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p051·原文件第56行", "note": "原文：辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。；核对说明：官员任命明确在辛丑，与己亥即位相隔，不合并同日。", "status": "draft", "id": "62328a1e-0b98-5241-b3ff-918300b79894", "subject_id": "a8b0614b-8e01-55bf-8de3-f52ed0feda35", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "王建封次子王宗懿为遂王，长子王宗仁因病被废。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p051·原文件第56行", "note": "原文：蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明：封王的具体日次未载；“幼以疾废”是追叙，不能定为907年新废黜。", "status": "draft", "id": "452c1790-99f3-59b0-9591-757a361562bd", "subject_id": "a8b0614b-8e01-55bf-8de3-f52ed0feda35", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》卷六十三也记九月己亥王建即位。", "citation": "《新五代史》卷六十三，段落 xin-wudaishi-b08f244b9241-p003188；EPUB电子本，纸本及异文待核", "note": "原文：秋九月己亥，建乃即皇帝位。；核对说明：新史前句祥瑞叙述不作为即位的因果事实。", "status": "draft", "id": "1478ef37-8a1f-5d28-aecf-39efdf0f5f9e", "subject_id": "fe13c8b8-7b97-5141-bde8-b2e496f0b1c9", "source_id": "33184c96-dda8-581a-b8ce-07720528d5d0"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》亦列王宗佶中书令、韦庄判中书门下事和唐袭枢密使。", "citation": "《新五代史》卷六十三，段落 xin-wudaishi-b08f244b9241-p003188；EPUB电子本，纸本及异文待核", "note": "原文：以王宗佶為中書令，韋莊為左散騎常侍判中書門下之事，唐襲為樞密使；核对说明：“唐襲”与主书“唐道袭”字形/称名差异并列，未仅凭省称创设新主体。", "status": "draft", "id": "5ca2cab8-0dcb-5639-898e-7b264c8c319c", "subject_id": "a8b0614b-8e01-55bf-8de3-f52ed0feda35", "source_id": "33184c96-dda8-581a-b8ce-07720528d5d0"}, {"subject_table": "event", "field_path": "description", "claim_text": "楚军击败淮南救雷彦恭之军，俘泠业李饶。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p052·原文件第57行", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。；核对说明：先记高季昌与楚军攻朗州，再记淮南救援及楚军反击；不把各次战事压成同日。", "status": "draft", "id": "9446b24b-9f92-52a3-82bc-25d3221d0035", "subject_id": "dd736a34-d63a-59b3-91e7-d10c3e267765", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年十月", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p052·原文件第57行", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。；核对说明：先记高季昌与楚军攻朗州，再记淮南救援及楚军反击；不把各次战事压成同日。", "status": "draft", "id": "8fb1f6b4-385c-5484-8216-f00ef34c81f8", "subject_id": "dd736a34-d63a-59b3-91e7-d10c3e267765", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "许德勋率楚军击败淮南援军，俘泠业、李饶后于长沙处死。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p052·原文件第57行", "note": "原文：又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明：泠业被俘见前句“擒业”；本句说明李饶被俘及二人后被斩。", "status": "draft", "id": "c0930abf-a52a-58d4-86b9-5a91c3303320", "subject_id": "dd736a34-d63a-59b3-91e7-d10c3e267765", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》卷六十六概述雷彦恭召吴人攻平江而许德勋击败之。", "citation": "《新五代史》卷六十六，段落 xin-wudaishi-b08f244b9241-p003313；EPUB电子本，纸本及异文待核", "note": "原文：朗州雷彥恭召吳人攻平江，許德勳擊敗之。；核对说明：新史紧接着叙雷彦恭后来出奔，未据此把后续结果倒填到本段。", "status": "draft", "id": "857637d4-50bd-58d7-84db-f7f378e8f43a", "subject_id": "dd736a34-d63a-59b3-91e7-d10c3e267765", "source_id": "9b5b05ed-ea26-5e2c-84c8-e67e8c190d67"}, {"subject_table": "event", "field_path": "description", "claim_text": "尹皓攻取晋军江猪岭寨。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p053·原文件第58行", "note": "原文：十一月，甲申，夹马指挥使尹皓攻晋江猪岭寨，拔之。；核对说明：主书未交代此寨后续归属，不作外推。", "status": "draft", "id": "efded27d-ad23-5fea-b0c8-a8eaba8b5e25", "subject_id": "e4d42907-4f57-5521-ae13-b1cb1399f2bb", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年十一月甲申", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p053·原文件第58行", "note": "原文：十一月，甲申，夹马指挥使尹皓攻晋江猪岭寨，拔之。；核对说明：主书未交代此寨后续归属，不作外推。", "status": "draft", "id": "5c99e347-1a71-5b10-92bc-7c48e91f8e6b", "subject_id": "e4d42907-4f57-5521-ae13-b1cb1399f2bb", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "刘守文因刘守光囚父而举兵相攻。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p054·原文件第59行", "note": "原文：义昌节度使刘守文闻其弟守光幽其父，集将吏大哭曰：“不意吾家生此枭獍！吾生不如死，誓与诸君讨之！”乃发兵击守光，互有胜负。；核对说明：“闻其弟守光幽其父”为先前事实；本段新事是刘守文起兵，双方互有胜负。", "status": "draft", "id": "3ab7f0b5-cc59-5caf-aa16-4d72a2c14839", "subject_id": "4470dce0-0e2b-5c1f-8f31-b2b7897d1652", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年十一月条；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p054·原文件第59行", "note": "原文：义昌节度使刘守文闻其弟守光幽其父，集将吏大哭曰：“不意吾家生此枭獍！吾生不如死，誓与诸君讨之！”乃发兵击守光，互有胜负。；核对说明：“闻其弟守光幽其父”为先前事实；本段新事是刘守文起兵，双方互有胜负。", "status": "draft", "id": "34c1b3e4-7b05-5109-a438-d113c864b33b", "subject_id": "4470dce0-0e2b-5c1f-8f31-b2b7897d1652", "source_id": "bb498404-6955-5987-8171-6ecfb192f367"}, {"subject_table": "event", "field_path": "description", "claim_text": "罗绍威致书劝降后刘守文请降于梁并送子为质。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p055·原文件第60行", "note": "原文：守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。；核对说明：请降与送质为主书记载；不将罗绍威的判断写作不战占领沧州。", "status": "draft", "id": "c6cc0b30-5f2f-52b0-8492-2f955b4cf9f6", "subject_id": "467cee9e-49ef-5b6e-a56c-b22fc21411f2", "source_id": "06613554-d527-5daa-afa7-2247745fec0d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年十一月戊子", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p055·原文件第60行", "note": "原文：守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。；核对说明：请降与送质为主书记载；不将罗绍威的判断写作不战占领沧州。", "status": "draft", "id": "509f61ce-b2c6-5916-ab70-7a68478be1d8", "subject_id": "467cee9e-49ef-5b6e-a56c-b22fc21411f2", "source_id": "06613554-d527-5daa-afa7-2247745fec0d"}, {"subject_table": "event", "field_path": "description", "claim_text": "后梁加刘守文中书令并予安抚。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p055·原文件第60行", "note": "原文：加守文中书令，抚纳之。；核对说明：此为请降后的授官，不推定刘守文与刘守光战争当即结束。", "status": "draft", "id": "4f0a70ec-1394-59e2-b400-1711aa0bd5b5", "subject_id": "467cee9e-49ef-5b6e-a56c-b22fc21411f2", "source_id": "06613554-d527-5daa-afa7-2247745fec0d"}, {"subject_table": "event", "field_path": "description", "claim_text": "后梁赦逃亡军士并允许有面纹者还乡。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p056·原文件第61行", "note": "原文：壬寅，诏赦其罪，自今虽文面亦听还乡里。盗减什七八。；核对说明：“盗减什七八”为主书效果概述，非可核现代统计；前述跋队斩和文面之设属追叙。", "status": "draft", "id": "cc6836c3-1328-5973-92a8-e5194c2db335", "subject_id": "abb7f5d9-9f17-5bc2-a219-9ea5b59a5b22", "source_id": "06613554-d527-5daa-afa7-2247745fec0d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年十一月壬寅", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p056·原文件第61行", "note": "原文：壬寅，诏赦其罪，自今虽文面亦听还乡里。盗减什七八。；核对说明：“盗减什七八”为主书效果概述，非可核现代统计；前述跋队斩和文面之设属追叙。", "status": "draft", "id": "09877d07-46b0-59ca-8c43-ba5a00ceabe4", "subject_id": "abb7f5d9-9f17-5bc2-a219-9ea5b59a5b22", "source_id": "06613554-d527-5daa-afa7-2247745fec0d"}, {"subject_table": "event", "field_path": "description", "claim_text": "朱温此前使用跋队斩与士兵文面制度，导致逃兵难以归乡。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p056·原文件第61行", "note": "原文：初，帝在籓镇，用法严，将校有战没者，所部兵悉斩之，谓之跋队斩。；核对说明：“初”明确追叙旧制，起始年未载；本年新措施为赦免。", "status": "draft", "id": "14310c40-3a68-577e-a3db-37951cead4bb", "subject_id": "abb7f5d9-9f17-5bc2-a219-9ea5b59a5b22", "source_id": "06613554-d527-5daa-afa7-2247745fec0d"}, {"subject_table": "event", "field_path": "description", "claim_text": "淮南米志诚攻颍州外郭，张实守子城。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p057·原文件第62行", "note": "原文：淮南右都押牙米志诚等将兵渡淮袭颍州，克其外郭。刺史张实据子城拒守。；核对说明：淮南军仅克外郭，刺史继续守子城；援军后续在第59段。", "status": "draft", "id": "3872d84a-24ac-59ee-a823-40ccd8825bd5", "subject_id": "ccb109d3-0568-51d4-b469-bccfcd8447ce", "source_id": "06613554-d527-5daa-afa7-2247745fec0d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年十一月壬寅后、十二月前；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p057·原文件第62行", "note": "原文：淮南右都押牙米志诚等将兵渡淮袭颍州，克其外郭。刺史张实据子城拒守。；核对说明：淮南军仅克外郭，刺史继续守子城；援军后续在第59段。", "status": "draft", "id": "b1acbfe6-3d1a-524a-8fa5-6da09acb8bba", "subject_id": "ccb109d3-0568-51d4-b469-bccfcd8447ce", "source_id": "06613554-d527-5daa-afa7-2247745fec0d"}, {"subject_table": "event", "field_path": "description", "claim_text": "李克用命李存璋攻晋州牵制上党梁军。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p058·原文件第63行", "note": "原文：晋王命李存璋攻晋州，以分上党兵势。十二月，壬戌，诏河中、陕州发兵救之。；核对说明：把晋军攻城与梁廷壬戌救援诏区分；不擅定攻城确日。", "status": "draft", "id": "2e56f58c-8242-522c-9d18-3f19ddd25489", "subject_id": "ae19efb9-c6a0-5abe-8dae-cb89db82f5cd", "source_id": "06613554-d527-5daa-afa7-2247745fec0d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年十二月壬戌梁诏救援；晋